LOG_ERREUR = os.path.join(
    os.environ.get("LOCALAPPDATA") or os.path.expanduser("~"),
    "Solynov", "erreur.log")


def _journaliser(msg):
    try:
        os.makedirs(os.path.dirname(LOG_ERREUR), exist_ok=True)
        with open(LOG_ERREUR, "w", encoding="utf-8") as f:
            f.write(msg)
    except Exception:
        pass


# tkinter est livre avec Python ; s'il manque, on trace une erreur lisible.
try:
    import tkinter as tk
    from tkinter import filedialog, messagebox
except Exception:
    _journaliser(
        "Le composant graphique 'tkinter' est introuvable.\n\n"
        + traceback.format_exc()
        + "\nSous Windows : reinstallez Python depuis python.org en cochant "
          "l'option 'tcl/tk and IDLE' pendant l'installation.\n"
          "Sous macOS : installez Python depuis python.org (pas la version "
          "minimale du systeme).")
    raise

# CustomTkinter : surcouche moderne. Chargee de facon tolerante pour que la
# verification des dependances (plus bas) affiche un message clair si absente.
try:
    import customtkinter as ctk
except Exception:
    ctk = None

# --- Correctif CustomTkinter : _check_if_valid_scroll plante ('str' object has no
#     attribute 'master') quand une liste deroulante ttk est dans un cadre defilant et
#     qu'on utilise la molette. On rend la verification tolerante aux widgets-chaine. ---
try:
    from customtkinter.windows.widgets.ctk_scrollable_frame import CTkScrollableFrame as _CTkSF
    _orig_valid_scroll = _CTkSF._check_if_valid_scroll
    def _valid_scroll_sur(self, widget):
        if isinstance(widget, str):
            try:
                widget = self.nametowidget(widget)
            except Exception:
                return False
        try:
            return _orig_valid_scroll(self, widget)
        except Exception:
            return False
    _CTkSF._check_if_valid_scroll = _valid_scroll_sur
except Exception:
    pass

# Backend et module Bridge : charges plus tard (dans main), une fois les
# dependances confirmees.
backend = None
bridge = None
BRIDGE_DISPO = False

# pip_name -> module importable
_DEPENDANCES = {
    "customtkinter": "customtkinter",
    "openpyxl": "openpyxl",
    "factur-x": "facturx",
    "reportlab": "reportlab",
    "pillow": "PIL",
    # saxonche : moteur XSLT requis par factur-x pour la validation schematron
    # BR-FR / EN 16931. S'il manque, factur-x saute SILENCIEUSEMENT la validation
    # de conformite -> on en fait une dependance dure (blocage clair au lancement).
    "saxonche": "saxonche",
}


def _modules_manquants():
    manquants = []
    for pip_name, module in _DEPENDANCES.items():
        try:
            __import__(module)
        except ImportError:
            manquants.append(pip_name)
    return manquants


