_SOLYNOV_LOGO_B64 = ""
def _solynov_logo():
    try:
        if _PILImage is None:
            return None
        return _PILImage.open(_io.BytesIO(_b64.b64decode(_SOLYNOV_LOGO_B64)))
    except Exception:
        return None

