def _config_dir_bureau():
    """Dossier de config local a la machine, par edition (licence.lic, essai.jeton)."""
    if platform.system() == "Windows":
        base = os.environ.get("LOCALAPPDATA") or os.path.expanduser("~")
    else:
        base = os.environ.get("XDG_CONFIG_HOME") or \
            os.path.join(os.path.expanduser("~"), ".config")
    d = os.path.join(base, "Solynov", "bridge" if BRIDGE_DISPO else "starter")
    try:
        os.makedirs(d, exist_ok=True)
    except Exception:
        pass
    return d

TXT_GEN      = "Générer les factures"
