        root.report_callback_exception = self._erreur_callback
        self._demarrer_diagnostic = diagnostic
        self.ods = tk.StringVar()

        edition = "Bridge" if BRIDGE_DISPO else "Starter"
        root.title(f"Solynov \u00b7 FacturX Facile ({edition})")
        root.geometry("720x680")
        root.minsize(680, 600)

