        corps.grid(row=4, column=0, sticky="nsew")
        corps.grid_columnconfigure(0, weight=1)
        PADX = 18

        def _carte(rang, num, titre):
            c = ctk.CTkFrame(corps, fg_color=BLANC, border_color=BORD_L,
                             border_width=1, corner_radius=12)
            c.grid(row=rang, column=0, sticky="ew", padx=PADX, pady=(10, 0))
            c.grid_columnconfigure(0, weight=1)
            tete = ctk.CTkFrame(c, fg_color=BLANC)
            tete.grid(row=0, column=0, sticky="ew", padx=13, pady=(11, 2))
            ctk.CTkLabel(tete, text=str(num), width=22, height=22, corner_radius=11,
                         fg_color=BLEU, text_color=BLANC,
                         font=ctk.CTkFont(size=12, weight="bold")).pack(side="left")
            ctk.CTkLabel(tete, text=titre, text_color=NAVY,
                         font=self.f_h).pack(side="left", padx=(9, 8))
            return c

        def _grille(parent, boutons, cols=3):
            g = ctk.CTkFrame(parent, fg_color=BLANC)
            for cc in range(cols):
                g.grid_columnconfigure(cc, weight=1, uniform="g")
            for i, (txt, cmd) in enumerate(boutons):
                ctk.CTkButton(g, text=txt, command=cmd, height=30, corner_radius=8,
                              fg_color=BLEU_LT, hover_color=BLEU_LT_D, text_color=NAVY,
                              border_color=BLEU_BORD, border_width=1,
                              font=self.f_btn).grid(row=i // cols, column=i % cols,
                                                    sticky="ew", padx=3, pady=3)
            return g

