    # ----------------------------------------------------------------- utils
    def _erreur_callback(self, exc, val, tb):
        import traceback as _t
        try:
            _journaliser("".join(_t.format_exception(exc, val, tb)))
        except Exception:
            pass
        try:
            messagebox.showerror("Erreur", "Une erreur est survenue :\n\n"
                                 + str(val) + "\n\n(Detail dans erreur.log.)")
        except Exception:
            pass

    def log(self, msg):
        try:
            self.statut.configure(text=msg)
            self.root.update_idletasks()
        except Exception:
            pass

    def _ods_valide(self):
        chemin = self.ods.get().strip()
        if not chemin or not os.path.isfile(chemin):
            messagebox.showwarning(
                "Classeur manquant",
                "Choisissez d'abord un classeur .xlsx (ou creez un modele).")
            return None
        return chemin

    def _rafraichir_info(self):
        # l'info du poste = le dossier des données (le registre est désormais interne)
        if hasattr(self, "info"):
            self._maj_info_donnees()

    # --------------------------------------------------------------- actions
    def _dossier_initial(self):
        """Dossier d'ouverture des fenetres de selection : celui du classeur
        en cours si valide, sinon le Bureau, sinon le dossier personnel.
        Evite que Windows retombe sur un lecteur reseau deconnecte."""
        chemin = self.ods.get().strip()
        if chemin:
            d = os.path.dirname(os.path.abspath(chemin))
            if os.path.isdir(d):
                return d
        for cand in (os.path.join(os.path.expanduser("~"), "Desktop"),
                     os.path.join(os.path.expanduser("~"), "Bureau"),
                     os.path.expanduser("~")):
            if os.path.isdir(cand):
                return cand
        return os.getcwd()

    def parcourir(self):
        chemin = filedialog.askopenfilename(
            title="Choisir un classeur",
            initialdir=self._dossier_initial(),
            filetypes=[("Classeur Excel", "*.xlsx"), ("Tous", "*.*")])
        if chemin:
            self.ods.set(chemin)
            self._rafraichir_info()
            self.log(f"Classeur charge : {chemin}")

