    def champs_optionnels(self):
        chemin = self._ods_valide()
        if not chemin:
            return
        try:
            presents = backend.champs_presents(chemin)
        except Exception as e:
            messagebox.showerror("Erreur", str(e))
            return

        fen = ctk.CTkToplevel(self.root)
        fen.title("Champs optionnels")
        fen.geometry("560x560")
        fen.transient(self.root)
        fen.after(120, fen.grab_set)   # grab differe (fenetre CTk pas encore prete)
        fen.configure(fg_color=FOND)

        ctk.CTkLabel(
            fen, justify="left", text_color=ARDOISE, font=self.f_body,
            text="Cochez les champs a ajouter au classeur. Seuls ceux dont\n"
                 "vous avez besoin sont utiles : les autres restent invisibles.\n"
                 "Les champs deja presents sont coches et grises.").pack(
            anchor="w", padx=16, pady=(14, 6))

        zone = ctk.CTkScrollableFrame(fen, fg_color=BLANC,
                                      border_color=BORD_L, border_width=1,
                                      corner_radius=8)
        zone.pack(fill="both", expand=True, padx=16, pady=(0, 6))

        vars_par_nom = {}
        groupe_courant = None
        for groupe, _cible, nom, desc, _val in backend.CHAMPS_OPTIONNELS:
            if groupe != groupe_courant:
                ctk.CTkLabel(zone, text=groupe, text_color=NAVY,
                             font=self.f_h, anchor="w").pack(
                    anchor="w", padx=8, pady=(10, 2), fill="x")
                groupe_courant = groupe
            deja = nom in presents
            var = tk.BooleanVar(value=deja)
            vars_par_nom[nom] = (var, deja)
            ctk.CTkCheckBox(
                zone, variable=var, text=f"{nom}  \u2014  {desc}",
                font=self.f_body, text_color=ARDOISE,
                fg_color=BLEU, hover_color=BLEU_D, checkbox_width=20,
                checkbox_height=20,
                state="disabled" if deja else "normal").pack(
                anchor="w", padx=8, pady=3, fill="x")

        barre = ctk.CTkFrame(fen, fg_color=FOND)
        barre.pack(fill="x", padx=16, pady=(4, 14))

        def appliquer():
            a_ajouter = [nom for nom, (var, deja) in vars_par_nom.items()
                         if var.get() and not deja]
            if not a_ajouter:
                fen.destroy()
                return
            try:
                n = backend.ajouter_champs(chemin, a_ajouter)
            except backend.ClasseurVerrouilleError:
                messagebox.showerror(
                    "Classeur ouvert",
                    "Fermez le classeur dans Excel/LibreOffice avant d'ajouter des champs.")
                return
            except Exception as e:
                messagebox.showerror("Erreur", str(e))
                return
            fen.destroy()
            self._rafraichir_info()
            self.log(f"{n} champ(s) optionnel(s) ajoute(s) au classeur.")
            messagebox.showinfo(
                "Champs ajoutes",
                f"{n} champ(s) ajoute(s). Ouvrez le classeur pour les renseigner "
                "(une bulle explique chaque colonne).")

        ctk.CTkButton(barre, text="Ajouter au classeur", command=appliquer,
                      height=38, corner_radius=8, fg_color=BLEU,
                      hover_color=BLEU_D, text_color=BLANC,
                      font=self.f_btn).pack(side="right")
        ctk.CTkButton(barre, text="Annuler", command=fen.destroy, height=38,
                      corner_radius=8, fg_color=BLANC, hover_color=SURVOL_L,
                      text_color=NAVY, border_color=BORD, border_width=1,
                      font=self.f_btn).pack(side="right", padx=8)

    def ouvrir_registre(self):
        chemin = self._ods_valide()
        if not chemin:
            return
        try:
            backend.ouvrir_fichier(chemin)
        except Exception as e:
            messagebox.showerror("Erreur", f"Impossible d'ouvrir le registre :\n{e}")
            return
        self.log("Registre ouvert. Modifiez-le puis fermez-le : "
                 "l'application reviendra au premier plan.")
        threading.Thread(target=self._surveiller_registre,
                         args=(chemin,), daemon=True).start()

    def _surveiller_registre(self, chemin):
        import time
        # 1) attendre que le tableur prenne la main (verrou cree), max ~20 s
        verrou_vu = False
        for _ in range(40):
            if backend.registre_verrouille(chemin):
                verrou_vu = True
                break
            time.sleep(0.5)
        if not verrou_vu:
            return  # ouvert dans un simple lecteur : pas de retour automatique
        # 2) attendre la fermeture (verrou libere, confirme sur 2 lectures)
        libre = 0
        while True:
            time.sleep(1.0)
            if not backend.registre_verrouille(chemin):
                libre += 1
                if libre >= 2:
                    break
            else:
                libre = 0
        self.root.after(0, self._reprendre_focus)

    def _reprendre_focus(self):
        try:
            self.root.deiconify()
            self.root.lift()
            self.root.attributes("-topmost", True)
            self.root.after(400, lambda: self.root.attributes("-topmost", False))
            self.root.focus_force()
            self._rafraichir_info()
            self.log("Registre ferme : retour a l'application.")
        except Exception:
            pass

    def _dossier_modeles(self):
        d = os.path.join(os.path.expanduser("~"), ".solynov", "modeles_bridge")
        try:
            os.makedirs(d, exist_ok=True)
        except Exception:
            pass
        return d

    def _modele_pour_signature(self, signature):
        """Retourne le modele memorise le plus proche de la structure fournie.
        On tolere quelques colonnes en plus ou en moins (un export partiel peut
        omettre une colonne entierement vide) : on reconnait le modele si au moins
        85% de ses colonnes sont presentes dans l'export courant."""
        d = self._dossier_modeles()
        if not os.path.isdir(d):
            return None
        cur = set(signature or [])
        meilleur, meilleur_score = None, 0.0
        for f in os.listdir(d):
            if not f.endswith(".json"):
                continue
            try:
                with open(os.path.join(d, f), encoding="utf-8") as fp:
                    m = json.load(fp)
            except Exception:
                continue
            sig = set(m.get("signature") or [])
            if not sig or not m.get("liens"):
                continue
            score = len(sig & cur) / len(sig)      # part des colonnes du modele retrouvees
            if score > meilleur_score:
                meilleur, meilleur_score = m, score
        return meilleur if meilleur_score >= 0.85 else None

    def _enregistrer_modele(self, source, syn, liees):
        """Memorise la structure d'un import multi-tables : signature de la table
        principale + copie des tables liees (clients, pieces...) en cache, pour que
        les imports suivants n'aient besoin que de la table de factures."""
        liens = syn.get("liens") or []
        if not liens:
            return
        import hashlib
        sig = syn.get("signature_principale") or []
        h = hashlib.sha1("|".join(sig).encode("utf-8")).hexdigest()[:12]
        cache_dir = os.path.join(self._dossier_modeles(), f"cache_{h}")
        os.makedirs(cache_dir, exist_ok=True)
        par_nom = {os.path.basename(p): p for p in (liees or [])}
        liens_json = []
        for (nom, role, *_) in liens:
            cache = os.path.join(cache_dir, nom)
            src = par_nom.get(nom)
            try:
                if src and os.path.abspath(src) != os.path.abspath(cache):
                    shutil.copy2(src, cache)
            except Exception:
                pass
            liens_json.append({"role": role, "nom": nom,
                               "cache": cache if os.path.exists(cache) else None})
        modele = {"nom": os.path.splitext(os.path.basename(source))[0],
                  "signature": sig, "liens": liens_json}
        with open(os.path.join(self._dossier_modeles(), f"modele_{h}.json"),
                  "w", encoding="utf-8") as fp:
            json.dump(modele, fp, ensure_ascii=False, indent=2)

    def importer_bridge(self):
        """Bridge : importe un tableur/export client (ou une base multi-tables) et
        le convertit en registre Solynov pre-rempli. Les cases obligatoires
        manquantes sont surlignees en jaune ; il suffit de les completer puis de generer."""
        source = filedialog.askopenfilename(
            title="Importer la table principale (factures) a convertir",
            initialdir=self._dossier_initial(),
            filetypes=[("Tableurs", "*.xlsx *.xlsm"), ("Tous", "*.*")])
        if not source:
            return
        # Modele memorise : reconnait-on cette structure d'export ?
        liees = []
        modele = None
        try:
            modele = self._modele_pour_signature(bridge.signature_fichier(source))
        except Exception:
            modele = None

        sauver_modele = False
        if modele:
            # structure reconnue : les tables liees sont deja en memoire (cache)
            nb = len(modele.get("liens", []))
            reimport = messagebox.askyesno(
                "Structure reconnue",
                f"Structure reconnue : modele \u00ab {modele['nom']} \u00bb.\n\n"
                f"Les {nb} table(s) liee(s) (clients, pieces, societe...) sont DEJA EN "
                f"MEMOIRE depuis votre premiere importation.\n\n"
                f"Devez-vous les RE-IMPORTER ?\n\n"
                f"   NON  (recommande) : Bridge reutilise les tables memorisees.\n"
                f"     -> repondez NON si vos clients / pieces n'ont PAS change.\n\n"
                f"   OUI : uniquement si ces tables ont ete MODIFIEES depuis la 1re fois\n"
                f"     (nouveau client, nouvelle piece, adresse corrigee...).")
            cache_liees = [l["cache"] for l in modele.get("liens", [])
                           if l.get("cache") and os.path.exists(l["cache"])]
            if reimport:
                sel = list(filedialog.askopenfilenames(
                    title="Re-selectionnez TOUTES les tables liees (Ctrl / Cmd + clic)",
                    initialdir=os.path.dirname(os.path.abspath(source)),
                    filetypes=[("Tableurs", "*.xlsx *.xlsm"), ("Tous", "*.*")]))
                if sel:
                    liees = sel
                    sauver_modele = True
                else:
                    liees = cache_liees      # annulation -> on garde la memoire
                    self.log("Bridge : re-import annule, tables liees reutilisees "
                             "depuis la memoire.")
            else:
                liees = list(cache_liees)
                manquants = [l["nom"] for l in modele.get("liens", [])
                             if not (l.get("cache") and os.path.exists(l["cache"]))]
                if manquants:
                    messagebox.showinfo(
                        "Tables liees a re-fournir",
                        "Ces tables memorisees sont introuvables et doivent etre "
                        "re-selectionnees :\n- " + "\n- ".join(manquants))
                    liees += list(filedialog.askopenfilenames(
                        title="Selectionnez les tables liees manquantes",
                        initialdir=os.path.dirname(os.path.abspath(source)),
                        filetypes=[("Tableurs", "*.xlsx *.xlsm"), ("Tous", "*.*")]))
                    sauver_modele = bool(liees)
                else:
                    self.log(f"Bridge : structure reconnue (modele \u00ab {modele['nom']} \u00bb) - "
                             f"{len(liees)} table(s) liee(s) reutilisee(s) depuis la memoire.")
            # securite : un modele reconnu ne doit jamais retomber en mono-table
            if not liees and cache_liees:
                liees = cache_liees
        else:
            # premiere fois : proposer d'ajouter les tables liees (Cas 3)
            if messagebox.askyesno(
                    "Tables liees ?",
                    "Vos donnees sont-elles reparties sur plusieurs tables ?\n\n"
                    "Si votre table de factures renvoie a d'autres tables (clients, "
                    "pieces/articles, societe...), ajoutez-les : Bridge les joindra "
                    "automatiquement pour completer le registre.\n\n"
                    "IMPORTANT : a l'ecran suivant, selectionnez TOUTES les tables liees "
                    "EN UNE SEULE FOIS (Ctrl+clic, ou Cmd+clic sur Mac, pour en choisir "
                    "plusieurs). Si vous en oubliez une, la jointure sera incomplete et le "
                    "registre vous demandera des corrections inutiles.\n\n"
                    "Elles seront MEMORISEES : aux imports suivants, vous n'aurez plus "
                    "qu'a fournir la table de factures.\n\n"
                    "Oui = choisir les tables liees   |   Non = une seule table"):
                liees = list(filedialog.askopenfilenames(
                    title="Selectionnez TOUTES les tables liees d'un coup "
                          "(Ctrl+clic / Cmd+clic pour selection multiple)",
                    initialdir=os.path.dirname(os.path.abspath(source)),
                    filetypes=[("Tableurs", "*.xlsx *.xlsm"), ("Tous", "*.*")]))
                sauver_modele = bool(liees)
        defaut = os.path.splitext(os.path.basename(source))[0] + "_registre_solynov.xlsx"
        cible = filedialog.asksaveasfilename(
            title="Enregistrer le registre Solynov genere",
            initialdir=os.path.dirname(os.path.abspath(source)),
            initialfile=defaut, defaultextension=".xlsx",
            filetypes=[("Classeur Excel", "*.xlsx")])
        if not cible:
            return
        try:
            if liees:
                self.log(f"Bridge : jointure de {os.path.basename(source)} "
                         f"+ {len(liees)} table(s) liee(s)...")
                syn = bridge.vers_registre_multi(source, liees, cible, backend)
                for nom, role, taux, cm, cl in syn["liens"]:
                    self.log(f"  jointure {role}: {nom} ({cm}={cl}, {int(taux*100)}%)")
                self.log(f"  {syn['factures']} facture(s), {syn['lignes']} ligne(s), "
                         f"{syn['clients']} client(s) | clients resolus "
                         f"{syn['clients_resolus']}/{syn['factures']}, designations "
                         f"{syn['lignes_resolues']}/{syn['lignes']}.")
                self.log(f"  {syn['a_completer']} case(s) a completer, "
                         f"{syn.get('a_revoir', 0)} facture(s) 'a revoir' (avoirs ?).")
                msg = (f"Jointure reussie.\n\n"
                       f"{syn['factures']} facture(s), {syn['lignes']} ligne(s), "
                       f"{syn['clients']} client(s).\n"
                       f"Clients resolus : {syn['clients_resolus']}/{syn['factures']}\n"
                       f"Designations resolues : {syn['lignes_resolues']}/{syn['lignes']}\n\n")
                if syn.get("a_avoir"):
                    msg += (f"{syn['a_avoir']} avoir(s) detecte(s) (montants entierement "
                            f"negatifs) : convertis en AVOIRS (type 381, montants positifs), "
                            f"prets a generer.\n")
                if syn.get("a_revoir"):
                    msg += (f"{syn['a_revoir']} facture(s) mixtes (remise partielle) mises "
                            f"en 'a revoir' - a traiter manuellement.\n")
                # memoriser la structure + les tables liees pour les imports suivants
                if sauver_modele:
                    try:
                        self._enregistrer_modele(source, syn, liees)
                        if not modele:
                            msg += ("\nStructure et tables liees MEMORISEES : au prochain "
                                    "import, fournissez seulement la table de factures. "
                                    "Bridge reutilisera les tables liees en memoire "
                                    "(repondez NON a \u00ab les re-importer ? \u00bb si clients et "
                                    "pieces n'ont pas change).\n")
                    except Exception:
                        pass
            else:
                self.log(f"Bridge : lecture de {os.path.basename(source)}...")
                syn = bridge.vers_registre(source, cible, backend)
                self.log(f"Bridge : {syn['reconnues']} colonnes reconnues, "
                         f"{syn['factures']} facture(s), {syn['lignes']} ligne(s), "
                         f"{syn['clients']} client(s).")
                if syn.get("a_confirmer"):
                    self.log(f"  A verifier une fois : {', '.join(syn['a_confirmer'])}")
                self.log(f"  {syn['a_completer']} case(s) a completer (surlignees en jaune).")
                msg = (f"Import reussi.\n\n{syn['factures']} facture(s), "
                       f"{syn['lignes']} ligne(s), {syn['reconnues']} colonnes reconnues.\n\n")
            self.ods.set(cible)
            self._rafraichir_info()
            if syn["a_completer"]:
                msg += (f"{syn['a_completer']} information(s) obligatoire(s) manquante(s) : "
                        f"les cases sont SURLIGNEES EN JAUNE dans le registre.\n"
                        f"Completez-les, enregistrez, puis cliquez sur GENERER.")
            else:
                msg += "Tout est complet : vous pouvez cliquer sur GENERER."
            messagebox.showinfo("Bridge - import termine", msg)
            try:
                backend.ouvrir_fichier(cible)
                threading.Thread(target=self._surveiller_registre,
                                 args=(cible,), daemon=True).start()
            except Exception:
                pass
        except Exception as e:
            messagebox.showerror("Bridge - erreur", str(e))
            self.log(f"Bridge ERREUR : {e}")

    def tester_conformite(self):
        """Teste que les tables exportées suffisent à fabriquer des Factur-X :
        jointure -> facture de test -> rapport de conformité affiché à l'écran."""
        if _verif is None:
            messagebox.showinfo("Vérification", "Module de vérification indisponible.")
            return
        # réutilise le dossier/tables déjà configurés ; sinon, les demande une fois
        principale, liees = (_cfg.tables_valides(self._config) if _cfg else (None, []))
        if principale:
            principale, liees = self._relire_tables_liees()   # état réel du dossier
        else:
            self._rediriger_cadre1()
            return
        travail = os.path.join(tempfile.gettempdir(), "solynov_verification")
        self.log("Vérification de conformité en cours (lecture des tables, "
                 "facture de test)…")
        self.root.configure(cursor="watch")
        try:
            self.barre_conf.grid()
            self.barre_conf.configure(mode="determinate")
            self.barre_conf.set(0)
        except Exception:
            pass

        def tache():
            try:
                rapport = _verif.verifier(principale, liees, travail,
                                          progression=self._progress_cb_conf)
                # Rapport UNIQUE : on joint l'analyse de correspondance pour que la
                # confirmation des colonnes se fasse dans le même écran que les
                # champs obligatoires manquants (un seul temps de vérification).
                try:
                    rapport["analyse"] = bridge.analyser_correspondance(principale, liees or [])
                except Exception:
                    rapport["analyse"] = None
            except Exception as e:
                self.root.after(0, lambda: (self._arreter_barre_conf(),
                    self.root.configure(cursor=""),
                    messagebox.showerror("Vérification", f"Échec : {e}")))
                return
            self.root.after(0, lambda: (self._arreter_barre_conf(),
                                        self._afficher_resultat(rapport)))
        threading.Thread(target=tache, daemon=True).start()

    def _progress_cb_conf(self, i, total, num):
        # appelé depuis le thread de vérification -> marshalé sur le thread principal
        self.root.after(0, self._maj_barre_conf, i, total)

    def _maj_barre_conf(self, i, total):
        try:
            self.barre_conf.set(i / total if total else 0)
        except Exception:
            pass

    def _arreter_barre_conf(self):
        try:
            self.barre_conf.stop()
            self.barre_conf.configure(mode="determinate")
            self.barre_conf.set(0)
            self.barre_conf.grid_remove()
        except Exception:
            pass

    def _motifs_blocage(self, syn):
        """Motifs qui interdisent une génération conforme : des données OBLIGATOIRES
        sont absentes des tables. Renvoie une liste de messages clairs pour le client
        (liste vide = rien ne bloque)."""
        motifs = []
        if not syn:
            return motifs
        if syn.get("vendeur_ok") is False:
            motifs.append(
                "Vos coordonnées vendeur sont introuvables : la table qui porte vos "
                "nom, SIREN et adresse est absente ou vide. Une facture sans vendeur "
                "identifié n'est pas conforme.")
        lignes = syn.get("lignes", 0) or 0
        resolues = syn.get("lignes_resolues", lignes)
        if lignes and resolues < lignes:
            motifs.append(
                f"Libellés d'articles non reconnus ({resolues}/{lignes}) : la table "
                "des pièces (code → désignation) est absente ou incomplète. Sans "
                "libellé, les articles seraient illisibles sur la facture.")
        fac = syn.get("factures", 0) or 0
        cli = syn.get("clients_resolus", fac)
        if fac and cli < fac:
            motifs.append(
                f"Identifiants clients non reconnus ({cli}/{fac}) : le lien vers la "
                "table clients est rompu (colonne client absente de vos factures, ou "
                "clients absents de la table). Sans client identifié, la facture "
                "n'est pas conforme.")
        return motifs

    def _construire_registre_auto(self, principale, liees):
        """Reconstruit le registre en silence depuis les tables, dans le dossier
        des données, en préservant les réglages de perso du registre précédent."""
        dossier = os.path.dirname(os.path.abspath(principale))
        registre = os.path.join(dossier, "registre_solynov.xlsx")
        perso = {}
        if os.path.exists(registre):
            try:
                anciens = backend.lire_parametres(registre)
                perso = {k: anciens.get(k) for k in _PERSO_KEYS if anciens.get(k)}
            except Exception:
                perso = {}
        self.log("Construction du registre depuis vos tables…")
        self._derniere_syn = None
        cfg0 = _cfg.charger(self._config) if _cfg else {}
        over = cfg0.get("overrides") or None
        # Garde-fou anti « mémoire résiduelle » : des forçages de colonnes mémorisés
        # pour un AUTRE schéma de table casseraient la détection (ex. pièces à 0 alors
        # que le diagnostic voit tout). On ne les applique que s'ils ont été faits pour
        # le schéma courant ; sinon on les purge.
        if over:
            try:
                sig_now = bridge.signature_fichier(principale)
            except Exception:
                sig_now = None
            if cfg0.get("overrides_schema") != sig_now:
                over = None
                if _cfg:
                    _cfg.maj(self._config, overrides=None, overrides_schema=None)
        try:
            # Bridge = tables normalisées : TOUJOURS le moteur multi-tables, même sans
            # table liée, pour que l'absence de clients / pièces / vendeur soit détectée
            # (et bloquée) dès le premier examen, au lieu d'un faux « complet ».
            self._derniere_syn = bridge.vers_registre_multi(
                principale, liees or [], registre, backend, overrides=over)
        except Exception as e:
            self.btn_generer.configure(state="normal", text=TXT_GEN)
            messagebox.showerror("Construction",
                                 f"Lecture de vos tables impossible :\n{e}")
            return None
        # la config (choix explicites du client) est prioritaire sur l'ancien registre
        if _cfg:
            c = _cfg.charger(self._config)
            for cle_cfg, cle_reg in (("logo", "Logo"),
                                     ("dossier_sortie", "Dossier de sortie")):
                if c.get(cle_cfg):
                    perso[cle_reg] = c[cle_cfg]
        if perso:
            try:
                self._reappliquer_perso(registre, perso)
            except Exception:
                pass
        try:
            self.ods.set(registre); self._rafraichir_info()
        except Exception:
            pass
        return registre

    def _reappliquer_perso(self, registre, perso):
        from openpyxl import load_workbook
        wb = load_workbook(registre)
        if "Parametres" not in wb.sheetnames:
            return
        pa = wb["Parametres"]
        for row in pa.iter_rows(min_row=1):
            cle = str(row[0].value or "").strip()
            if cle in perso and perso[cle] not in (None, ""):
                row[1].value = perso[cle]
        wb.save(registre)

    # ---------------------------------------------------------- pré-vol
    def _signature_schema(self, syn):
        """Empreinte du schéma détecté : structure des tables + colonnes de
        facture. Change dès que la forme des tables change (nouvelle colonne,
        jointure différente…), ce qui redéclenche le pré-vol."""
        import hashlib
        parts = list(syn.get("signature_principale", []))
        for l in syn.get("liens", []):
            parts.append(f"{l[1]}|{l[3]}|{l[4]}")   # rôle | col_principale | col_liée
        for c, col in sorted((syn.get("mapping_facture") or {}).items()):
            parts.append(f"{c}={col}")
        return hashlib.sha1("\n".join(str(p) for p in parts).encode("utf-8")).hexdigest()

    def _prevol_necessaire(self, syn):
        """Vrai si le schéma n'a pas encore été validé (première fois) ou s'il a
        changé depuis la dernière validation."""
        if not syn:
            return False
        courante = self._signature_schema(syn)
        valide = (_cfg.charger(self._config).get("schema_valide") if _cfg else None)
        return courante != valide

    def _memoriser_schema_valide(self, syn):
        if _cfg and syn:
            _cfg.maj(self._config, schema_valide=self._signature_schema(syn))

    _ROLE_LBL = {"client": ("Clients", "ti"), "piece": ("Articles", "ti"),
                 "vendeur": ("Votre société", "ti")}
    _CIBLE_LBL = {"numero": "numéro", "date": "date", "client_nom": "client",
                  "designation": "désignation", "quantite": "quantité",
                  "prix_unitaire": "prix unitaire"}

    def _afficher_prevol(self, syn):
        """Montre ce que Solynov a compris des tables et demande validation AVANT
        de produire. Renvoie True si le client valide, False s'il veut revoir."""
        fen = ctk.CTkToplevel(self.root)
        fen.title("Vérifions vos données")
        fen.configure(fg_color=BLANC)
        fen.geometry("560x640")
        fen.transient(self.root)
        fen.grab_set()
        self._prevol_ok = False

        head = ctk.CTkFrame(fen, fg_color=BLANC)
        head.pack(fill="x", padx=18, pady=(16, 4))
        ctk.CTkLabel(head, text="Vérifions ce que Solynov a compris de vos tables",
                     text_color=NAVY, font=self.f_h, anchor="w").pack(anchor="w")
        ctk.CTkLabel(head, text="Rien n'est encore produit. Contrôlez, puis lancez la génération.",
                     text_color=ARDOISE_L, font=self.f_small, anchor="w").pack(anchor="w")

        # métriques
        mrow = ctk.CTkFrame(fen, fg_color=BLANC)
        mrow.pack(fill="x", padx=18, pady=(10, 4))
        for lbl, val in (("Factures", syn.get("factures", 0)),
                         ("Clients", syn.get("clients", 0)),
                         ("Lignes", syn.get("lignes", 0))):
            c = ctk.CTkFrame(mrow, fg_color=FOND, corner_radius=8)
            c.pack(side="left", expand=True, fill="x", padx=4)
            ctk.CTkLabel(c, text=lbl, text_color=ARDOISE_L, font=self.f_small).pack(pady=(8, 0))
            ctk.CTkLabel(c, text=str(val), text_color=NAVY,
                         font=ctk.CTkFont(size=22, weight="bold")).pack(pady=(0, 8))

        zone = ctk.CTkScrollableFrame(fen, fg_color=BLANC, height=340)
        zone.pack(fill="both", expand=True, padx=18, pady=(8, 4))

        ctk.CTkLabel(zone, text="Tables reliées", text_color=ARDOISE,
                     font=self.f_small, anchor="w").pack(anchor="w", pady=(0, 4))
        for nom, role, taux, col_main, col_liee in syn.get("liens", []):
            titre_role = self._ROLE_LBL.get(role, (role.capitalize(), "ti"))[0]
            sur = taux >= 0.95
            lien = f"reliée par « {col_main} » ↔ « {col_liee} »" if col_main else "détectée"
            ligne = ctk.CTkFrame(zone, fg_color=BLANC, border_color=BORD_L, border_width=1,
                                 corner_radius=8)
            ligne.pack(fill="x", pady=3)
            ligne.grid_columnconfigure(0, weight=1)
            txt = ctk.CTkFrame(ligne, fg_color=BLANC)
            txt.grid(row=0, column=0, sticky="w", padx=10, pady=8)
            ctk.CTkLabel(txt, text=f"{titre_role} — {nom}", text_color=NAVY,
                         font=self.f_body, anchor="w").pack(anchor="w")
            ctk.CTkLabel(txt, text=lien, text_color=ARDOISE_L, font=self.f_small,
                         anchor="w").pack(anchor="w")
            b_txt = "sûr" if sur else "à confirmer"
            b_fg = "#DCFCE7" if sur else AMBRE_LT
            b_tx = "#166534" if sur else AMBRE_TXT
            ctk.CTkLabel(ligne, text=b_txt, fg_color=b_fg, text_color=b_tx,
                         corner_radius=10, font=self.f_small, padx=10, pady=2).grid(
                row=0, column=1, sticky="e", padx=10)

        ctk.CTkLabel(zone, text="Colonnes de la facture", text_color=ARDOISE,
                     font=self.f_small, anchor="w").pack(anchor="w", pady=(12, 4))
        a_confirmer = set(syn.get("a_confirmer", []))
        colonnes = [str(c) for c in (syn.get("colonnes_principale") or [])]
        self._prevol_menus = {}   # cible -> (StringVar, colonne détectée)
        for cible, col in (syn.get("mapping_facture") or {}).items():
            if not col:
                continue
            douteux = cible in a_confirmer
            ligne = ctk.CTkFrame(zone, fg_color=(AMBRE_LT if douteux else BLANC),
                                 border_color=(AMBRE_BORD if douteux else BORD_L),
                                 border_width=1, corner_radius=8)
            ligne.pack(fill="x", pady=3)
            ligne.grid_columnconfigure(0, weight=1)
            lbl = self._CIBLE_LBL.get(cible, cible)
            if douteux and colonnes:
                ctk.CTkLabel(ligne, text=f"{lbl} — quelle colonne ?",
                             text_color=AMBRE_TXT, font=self.f_body, anchor="w").grid(
                    row=0, column=0, sticky="w", padx=10, pady=8)
                var = tk.StringVar(value=str(col))
                ctk.CTkOptionMenu(ligne, values=colonnes, variable=var, width=170,
                                  height=28, corner_radius=8, font=self.f_small,
                                  fg_color=BLANC, text_color=NAVY, button_color=BORD,
                                  button_hover_color=SURVOL_L, dropdown_fg_color=BLANC,
                                  dropdown_text_color=NAVY).grid(
                    row=0, column=1, sticky="e", padx=10, pady=6)
                self._prevol_menus[cible] = (var, str(col))
            else:
                ctk.CTkLabel(ligne, text=f"{lbl} → « {col} »", text_color=ARDOISE,
                             font=self.f_body, anchor="w").grid(row=0, column=0,
                             sticky="w", padx=10, pady=8)

        if a_confirmer:
            ctk.CTkLabel(fen, text="Les points « à confirmer » sont ceux où Solynov a un doute. "
                         "Choisissez la bonne colonne si besoin, puis générez.",
                         text_color=ARDOISE_L, font=self.f_small, anchor="w",
                         justify="left", wraplength=500).pack(anchor="w", padx=18, pady=(2, 0))

        bar = ctk.CTkFrame(fen, fg_color=BLANC)
        bar.pack(fill="x", padx=18, pady=(8, 14))

        def valider():
            # ne retenir que les colonnes réellement changées par le client
            self._prevol_overrides = {
                cible: var.get()
                for cible, (var, detectee) in self._prevol_menus.items()
                if var.get() and var.get() != detectee}
            self._prevol_ok = True
            fen.destroy()

        ctk.CTkButton(bar, text="Tout est correct — générer les Factur-X",
                      command=valider, height=40, corner_radius=10, fg_color=BLEU,
                      hover_color=BLEU_D, text_color=BLANC, font=self.f_btn).pack(
            side="left", expand=True, fill="x", padx=(0, 4))
        ctk.CTkButton(bar, text="Revoir mes tables", command=fen.destroy, height=40,
                      corner_radius=10, fg_color=BLANC, hover_color=SURVOL_L,
                      text_color=NAVY, border_color=BORD, border_width=1,
                      font=self.f_btn).pack(side="left", padx=(4, 0))

        self._prevol_overrides = {}
        self.root.wait_window(fen)
        return self._prevol_ok, dict(self._prevol_overrides)

    def _afficher_correspondance(self, analyse):
        """Écran « contrat » : une ligne par champ Factur-X, avec la colonne détectée
        (liste déroulante, colonnes groupées par table), un voyant, et une explication
        pour les termes techniques. Renvoie le contrat validé (dict) ou None si annulé."""
        VERT, AMBRE, ROUGE = "#16A34A", "#B45309", "#DC2626"
        from tkinter import ttk
        champs = sorted(analyse.get("champs", []), key=lambda c: (not c["obligatoire"],))
        opts = ["(non fourni)"]
        remap = {"(non fourni)": (None, None)}
        for table, cols in analyse.get("colonnes", {}).items():
            for col in cols:
                lib = f"{table} · {col}"
                opts.append(lib)
                remap[lib] = (table, col)

        fen = ctk.CTkToplevel(self.root)
        fen.title("Vérifions la correspondance de vos champs")
        fen.configure(fg_color=BLANC)
        fen.geometry("740x680")
        fen.transient(self.root)
        ctk.CTkLabel(fen, text="Vérifions la correspondance de vos champs",
                     text_color=NAVY, font=self.f_marque).pack(anchor="w", padx=20, pady=(16, 2))
        ctk.CTkLabel(fen, text="Confirmez où Solynov a trouvé chaque information. Fait une "
                     "seule fois ; tout écart futur (colonne retirée ou renommée) sera signalé.",
                     text_color=ARDOISE_L, font=self.f_small, anchor="w", justify="left",
                     wraplength=680).pack(anchor="w", padx=20, pady=(0, 8))
        zone = ctk.CTkScrollableFrame(fen, fg_color=BLANC, border_color=BORD, border_width=1)
        zone.pack(fill="both", expand=True, padx=16, pady=(0, 8))

        menus = {}
        for c in champs:
            r = ctk.CTkFrame(zone, fg_color=BLANC)
            r.pack(fill="x", padx=6, pady=(7, 0))
            haut = ctk.CTkFrame(r, fg_color=BLANC)
            haut.pack(fill="x")
            lab = c["label"] + (f"   {c['bt']}" if c["bt"] else "")
            if c["obligatoire"]:
                lab += "  (obligatoire)"
            ctk.CTkLabel(haut, text=lab, text_color=NAVY, font=self.f_h, anchor="w",
                         width=225, justify="left", wraplength=225).pack(side="left")
            var = tk.StringVar()
            depart = f"{c['table']} · {c['colonne']}" if c.get("colonne") else "(non fourni)"
            var.set(depart if depart in remap else "(non fourni)")
            cb = ttk.Combobox(haut, values=opts, textvariable=var, state="readonly",
                              width=46)
            cb.pack(side="left", padx=8)
            self._molette_defile_panneau(cb)
            coul = (VERT if c["statut"] == "ok" else AMBRE if c["statut"] == "a_confirmer"
                    else ROUGE)
            ctk.CTkLabel(haut, text="●", text_color=coul, font=self.f_body,
                         width=14).pack(side="left")
            if c.get("explication"):
                ctk.CTkLabel(r, text="↳ " + c["explication"], text_color=ARDOISE_L,
                             font=self.f_small, anchor="w", justify="left",
                             wraplength=680).pack(anchor="w", padx=(8, 0))
            menus[c["id"]] = (var, c)

        self._corr_result = None

        def valider():
            contrat = {"champs": []}
            for cid, (var, c) in menus.items():
                table, col = remap.get(var.get(), (None, None))
                contrat["champs"].append({
                    "id": cid, "cible": c["cible"], "role": c["role"],
                    "label": c["label"], "obligatoire": c["obligatoire"],
                    "table": table, "colonne": col})
            manquants = [c["label"] for _i, (var, c) in menus.items()
                         if c["obligatoire"] and remap.get(var.get(), (None, None))[1] is None]
            if manquants and not messagebox.askyesno(
                    "Champs obligatoires non fournis",
                    "Ces champs obligatoires ne sont associés à aucune colonne :\n\n"
                    + "\n".join("•  " + m for m in manquants[:12])
                    + "\n\nLa génération restera bloquée tant qu'ils manquent. "
                    "Valider quand même la correspondance ?"):
                return
            self._corr_result = contrat
            fen.destroy()

        bar = ctk.CTkFrame(fen, fg_color=BLANC)
        bar.pack(fill="x", padx=16, pady=(0, 14))
        ctk.CTkButton(bar, text="Valider la correspondance", command=valider, height=38,
                      corner_radius=10, fg_color=BLEU, hover_color=BLEU_D, text_color=BLANC,
                      font=self.f_btn).pack(side="right")
        ctk.CTkButton(bar, text="Revoir mes tables", command=fen.destroy, height=38,
                      corner_radius=10, fg_color=BLANC, hover_color=SURVOL_L, text_color=NAVY,
                      border_color=BORD, border_width=1, font=self.f_btn).pack(side="right",
                                                                              padx=(0, 8))
        fen.update_idletasks()
        try:
            fen.grab_set()
        except Exception:
            pass
        self._activer_retours_auto(fen)
        self.root.wait_window(fen)
        return self._corr_result

    def _verifier_correspondance(self, principale, liees):
        """1re fois : fait confirmer le contrat champ→colonne et le mémorise. Ensuite :
        détecte toute dérive (colonne disparue) et propose de revoir. Renvoie True si
        la génération peut continuer, False si elle doit s'arrêter."""
        if not _cfg:
            return True
        contrat = _cfg.charger(self._config).get("correspondance")
        if not contrat:
            try:
                analyse = bridge.analyser_correspondance(principale, liees or [])
            except Exception as e:
                messagebox.showerror("Correspondance", f"Analyse impossible : {e}")
                return False
            contrat = self._afficher_correspondance(analyse)
            if contrat is None:
                self.log("Correspondance non validée : génération annulée.")
                return False
            _cfg.maj(self._config, correspondance=contrat)
            self._appliquer_corrections(contrat)
            return True
        try:
            ecarts = bridge.contrat_ecarts(contrat, principale, liees or [])
        except Exception:
            ecarts = []
        if ecarts:
            lignes = "\n".join(f"•  {e['label']} : la colonne « {e['colonne']} » n'est "
                               f"plus dans {e['table']}" for e in ecarts[:12])
            if messagebox.askyesno(
                    "Vos tables ont changé",
                    "Depuis votre dernière validation, des colonnes utilisées ont disparu "
                    "(retirées ou renommées) :\n\n" + lignes
                    + "\n\nVoulez-vous revoir la correspondance maintenant ?"):
                try:
                    analyse = bridge.analyser_correspondance(principale, liees or [])
                except Exception as e:
                    messagebox.showerror("Correspondance", f"Analyse impossible : {e}")
                    return False
                nouveau = self._afficher_correspondance(analyse)
                if nouveau is None:
                    return False
                _cfg.maj(self._config, correspondance=nouveau)
                self._appliquer_corrections(nouveau)
                return True
            return False
        return True

    def _appliquer_corrections(self, contrat):
        """Traduit les colonnes confirmées de la table PRINCIPALE en 'overrides' pour
        que la détection suive le choix du client (les tables liées sont, elles,
        détectées par rôle)."""
        overrides = {e["cible"]: e["colonne"] for e in contrat.get("champs", [])
                     if e.get("role") == "facture" and e.get("colonne")}
        if _cfg:
            try:
                sig = bridge.signature_fichier(
                    _cfg.charger(self._config).get("table_principale"))
            except Exception:
                sig = None
            _cfg.maj(self._config, overrides=(overrides or None), overrides_schema=sig)

    def _revoir_correspondance(self):
        """Rouvre l'écran de correspondance à la demande (depuis le diagnostic), pour
        revoir/corriger le mapping champ→colonne et le ré-enregistrer."""
        principale, liees = (_cfg.tables_valides(self._config) if _cfg else (None, []))
        if not principale:
            messagebox.showinfo("Correspondance", "Configurez d'abord vos données "
                                "(bouton « Choisir les données »).")
            return
        principale, liees = self._relire_tables_liees()
        try:
            analyse = bridge.analyser_correspondance(principale, liees or [])
        except Exception as e:
            messagebox.showerror("Correspondance", f"Analyse impossible : {e}")
            return
        contrat = self._afficher_correspondance(analyse)
        if contrat is not None and _cfg:
            _cfg.maj(self._config, correspondance=contrat)
            self._appliquer_corrections(contrat)
            self.log("Correspondance des champs revue et enregistrée.")

    def _maj_info_donnees(self):
        if not hasattr(self, "info"):
            return
        cfg = _cfg.charger(self._config) if _cfg else {}
        dossier = cfg.get("dossier_donnees")
        if dossier:
            nb = len(cfg.get("tables_liees", [])) + 1
            self.info.configure(text=f"Dossier : {dossier}   ({nb} table(s))")
            if hasattr(self, "btn_dossier"):
                self.btn_dossier.configure(text="Relire les données")
        else:
            self.info.configure(text="Aucun dossier de données configuré.")
            if hasattr(self, "btn_dossier"):
                self.btn_dossier.configure(text="Choisir les données")
        if hasattr(self, "lbl_sortie"):
            explicite = cfg.get("dossier_sortie")
            if explicite:
                self.lbl_sortie.configure(text=f"Dossier de sortie : {explicite}")
            elif dossier:
                self.lbl_sortie.configure(
                    text="Dossier de sortie par défaut : "
                    + os.path.join(dossier, "Factures"))
            else:
                self.lbl_sortie.configure(text="")

    def choisir_dossier_donnees(self):
        principale, liees = self._configurer_donnees()
        if not principale:
            return
        # Un seul temps de vérification : au choix du dossier, Solynov reconstruit le
        # registre EN SILENCE (du mieux qu'il peut). La confirmation des correspondances
        # et le signalement des champs obligatoires manquants se font ensuite, ensemble,
        # dans le rapport unique du bouton « Tester la conformité ».
        self._construire_registre_auto(principale, liees)
        self._maj_info_donnees()

    def _rediriger_cadre1(self):
        """Aiguillage quand une action nécessite les données pas encore configurées."""
        messagebox.showinfo(
            "Vos données",
            "Commencez par le cadre 1 « Préparer vos données » : cliquez "
            "« Choisir les données » pour indiquer le dossier de vos tables "
            "exportées, puis revenez ici.")

    def _registre_courant(self):
        chemin = self.ods.get().strip()
        if chemin and os.path.exists(chemin):
            return chemin
        principale, liees = (_cfg.tables_valides(self._config) if _cfg else (None, []))
        if principale:
            return self._construire_registre_auto(principale, liees)
        self._rediriger_cadre1()
        return None

    def definir_dossier_sortie(self):
        cfg = _cfg.charger(self._config) if _cfg else {}
        init = cfg.get("dossier_sortie")
        if not (init and os.path.isdir(init)):
            init = self._dossier_initial()
        dossier = filedialog.askdirectory(
            title="Où enregistrer vos Factur-X ?", initialdir=init)
        if not dossier:
            return
        dossier = os.path.normpath(dossier)   # //SRVSAS22/... -> \\SRVSAS22\... (UNC propre)
        if _cfg:
            _cfg.maj(self._config, dossier_sortie=dossier)
        reg = self.ods.get().strip()
        if reg and os.path.exists(reg):
            try:
                self._reappliquer_perso(reg, {"Dossier de sortie": dossier})
            except Exception:
                pass
        self.log(f"Dossier de sortie : {dossier}")
        self._maj_info_donnees()
        messagebox.showinfo(
            "Dossier de sortie",
            "C'est noté. Vos Factur-X générées seront enregistrées ici :\n\n"
            + dossier)

    def _ouvrir_validateur(self, nom, url):
        """Explique la marche à suivre, puis ouvre le validateur en ligne."""
        messagebox.showinfo(
            "Validation externe — " + nom,
            "On va ouvrir le site " + nom + " dans votre navigateur.\n\n"
            "Sur ce site :\n"
            "  1) déposez une Factur-X que vous avez générée (elle se trouve "
            "dans votre dossier de sortie) ;\n"
            "  2) lancez la validation ;\n"
            "  3) le site indique si le fichier est conforme.\n\n"
            "C'est un contrôle indépendant, en complément de la vérification "
            "intégrée de Solynov.")
        webbrowser.open(url)

    def ouvrir_dossier_facturx(self):
        base = self._dossier_sortie()
        if not base or not os.path.isdir(base):
            messagebox.showinfo("Factur-X",
                                "Aucune facture générée pour l'instant.")
            return
        self._ouvrir_fichier(base)

    def ouvrir_registre_visuel(self):
        reg = self._registre_courant()
        if not reg or not os.path.exists(reg):
            return
        messagebox.showinfo(
            "Registre",
            "Le registre s'ouvre pour vous montrer, surlignées en JAUNE, les "
            "données manquantes.\n\nIMPORTANT : corrigez ces manques dans les "
            "tables de votre logiciel de gestion, PAS dans le registre "
            "(il est reconstruit à chaque génération).")
        self._ouvrir_fichier(reg)

    def _saisir_chemin_reseau(self):
        """Repli quand le lecteur reseau (type N:) n'apparait pas dans la fenetre
        de selection : le client colle le chemin RESEAU (UNC) de son dossier. Un
        chemin UNC (\\serveur\partage\...) reste accessible meme quand la lettre
        mappee n'est pas visible dans le contexte du process. Renvoie le chemin
        valide, ou None."""
        try:
            from tkinter import simpledialog
        except Exception:
            return None
        saisi = simpledialog.askstring(
            "Chemin reseau du dossier",
            "Votre dossier serveur n'apparait pas dans la fenetre "
            "(lecteur reseau non visible) ?\n\n"
            "Collez ici son chemin reseau complet, par exemple :\n"
            "    \\\\SRVSAS22\\partage\\Solynov_donnees\n\n"
            "Chemin :", parent=self.root)
        if not saisi:
            return None
        chemin = os.path.normpath(saisi.strip().strip('"'))
        if os.path.isdir(chemin):
            return chemin
        messagebox.showwarning(
            "Dossier introuvable",
            "Ce chemin n'est pas accessible :\n\n" + chemin +
            "\n\nVerifiez que le serveur est accessible, puis reessayez.")
        return None

    def _configurer_donnees(self):
        """Le client désigne UNE fois le dossier de ses données et sa table de
        factures ; les autres tableurs du dossier deviennent les tables liées.
        Le tout est mémorisé (config persistante) : plus de re-sélection ensuite."""
        dossier = filedialog.askdirectory(
            title="Dossier de vos données (où vous déposez vos tables exportées)",
            initialdir=self._dossier_initial())
        if not dossier:
            dossier = self._saisir_chemin_reseau()
        if not dossier:
            return None, []
        dossier = os.path.normpath(dossier)
        principale = filedialog.askopenfilename(
            title="Votre table de factures (dans ce dossier)",
            initialdir=dossier,
            filetypes=[("Tableurs", "*.xlsx *.xlsm"), ("Tous", "*.*")])
        if not principale:
            return None, []
        principale = os.path.normpath(principale)
        liees = []
        try:
            for f in sorted(os.listdir(dossier)):
                c = os.path.normpath(os.path.join(dossier, f))
                bas = f.lower()
                if (c != principale and bas.endswith((".xlsx", ".xlsm"))
                        and "registre_solynov" not in bas
                        and "_verification" not in bas
                        and "diagnostic" not in bas
                        and not f.startswith("~$")):
                    liees.append(c)
        except Exception:
            pass
        # Chemins en UNC (\\serveur\...) plutôt qu'en lettre mappée (N:) : le veilleur
        # d'assistance et le worker tournent en tâche planifiée, où les lecteurs mappés
        # n'existent pas — sinon ils ne trouvent ni les tables ni le signal d'anomalies.
        dossier = self._vers_unc(dossier)
        principale = self._vers_unc(principale)
        liees = [self._vers_unc(t) for t in liees]
        if _cfg:
            _cfg.maj(self._config, dossier_donnees=dossier,
                     table_principale=principale, tables_liees=liees)
        self.log(f"Données configurées : {os.path.basename(principale)} "
                 f"+ {len(liees)} table(s) liée(s) dans « {dossier} ».")
        return principale, liees

    def _relire_tables_liees(self):
        """Re-détecte les tables liées présentes dans le dossier configuré, sans rien
        redemander (même dossier, même table de factures). Ainsi, ajouter ou retirer
        une table dans le dossier est pris en compte automatiquement au moment de
        tester ou de générer — pas besoin de re-choisir le dossier."""
        cfg = _cfg.charger(self._config) if _cfg else {}
        dossier = cfg.get("dossier_donnees")
        principale = cfg.get("table_principale")
        if not dossier or not principale or not os.path.isdir(dossier):
            return principale, cfg.get("tables_liees", [])
        principale = os.path.normpath(principale)
        liees = []
        try:
            for f in sorted(os.listdir(dossier)):
                c = os.path.normpath(os.path.join(dossier, f))
                bas = f.lower()
                if (c != principale and bas.endswith((".xlsx", ".xlsm"))
                        and "registre_solynov" not in bas
                        and "_verification" not in bas
                        and "diagnostic" not in bas
                        and not f.startswith("~$")):
                    liees.append(c)
        except Exception:
            return principale, cfg.get("tables_liees", [])
        if _cfg:
            _cfg.maj(self._config, tables_liees=liees)
        return principale, liees

    _TACHE_GEN_AUTO = "Solynov - Recuperation auto"

    def _vers_unc(self, chemin):
        """Convertit un chemin sur lecteur réseau mappé (N:\\...) en chemin UNC
        (\\\\serveur\\partage\\...). Indispensable : les lettres de lecteur mappées
        n'existent pas dans le contexte d'une tâche planifiée. Renvoie le chemin
        inchangé si ce n'est pas un lecteur mappé (disque local, déjà UNC...)."""
        if not sys.platform.startswith("win") or not chemin:
            return chemin
        import re
        m = re.match(r"^([A-Za-z]):[\\/](.*)$", chemin)
        if not m:
            return chemin
        try:
            import ctypes
            from ctypes import wintypes
            buf = ctypes.create_unicode_buffer(1024)
            taille = wintypes.DWORD(1024)
            res = ctypes.windll.mpr.WNetGetConnectionW(
                m.group(1) + ":", buf, ctypes.byref(taille))
            if res == 0 and buf.value:
                return buf.value.rstrip("\\/") + "\\" + m.group(2)
        except Exception:
            pass
        return chemin

    def _creer_kit(self, dest):
        """Assemble dans `dest` un dossier « Solynov_recuperation_auto » prêt à
        tourner (exécutable/worker + config_tables.json + licence + scripts).
        Renvoie (chemin_kit, manquants). Lève en cas d'échec dur."""
        cfg = _cfg.charger(self._config) if _cfg else {}
        principale = cfg.get("table_principale")
        kit = os.path.join(dest, "Solynov_recuperation_auto")
        os.makedirs(os.path.join(kit, "config"), exist_ok=True)
        manquants = []
        if getattr(sys, "frozen", False):
            shutil.copyfile(sys.executable, os.path.join(kit, "solynov_fx.exe"))
        else:
            src = os.path.dirname(os.path.abspath(__file__))
            for m in ("solynov_worker.py", "bridge.py", "facturx_tableur.py",
                      "facturx_engine.py", "solynov_verif.py", "solynov_licence.py"):
                origine = os.path.join(src, m)
                if os.path.exists(origine):
                    shutil.copyfile(origine, os.path.join(kit, m))
                else:
                    manquants.append(m)
        conf = {"table_principale": self._vers_unc(principale),
                "tables_liees": [self._vers_unc(t)
                                 for t in cfg.get("tables_liees", [])]}
        # Dossier de sortie : on inscrit TOUJOURS le dossier effectif (choix explicite,
        # sinon « Factures » sous les données) pour que le worker écrive AU MÊME endroit
        # que la génération manuelle, et pas dans un sous-dossier local du kit.
        sortie = cfg.get("dossier_sortie")
        if not sortie and cfg.get("dossier_donnees"):
            sortie = os.path.join(cfg["dossier_donnees"], "Factures")
        if sortie:
            conf["dossier_sortie"] = self._vers_unc(sortie)
        if cfg.get("overrides"):
            conf["overrides"] = cfg["overrides"]
        with open(os.path.join(kit, "config_tables.json"), "w",
                  encoding="utf-8") as f:
            json.dump(conf, f, ensure_ascii=False, indent=2)
        lic = os.path.join(self._config, "licence.lic")
        jeton = os.path.join(self._config, "essai.jeton")
        if os.path.exists(lic):
            shutil.copyfile(lic, os.path.join(kit, "config", "licence.lic"))
        elif os.path.exists(jeton):
            # essai : jeton lié à CETTE machine ; la génération locale le validera.
            shutil.copyfile(jeton, os.path.join(kit, "config", "essai.jeton"))
        else:
            manquants.append("licence.lic")
        self._ecrire_scripts_kit(kit)
        return kit, manquants

    def _cmd_planif_gen(self, kit):
        """Ligne schtasks (pour .bat) installant la tâche de génération auto."""
        if getattr(sys, "frozen", False):
            action = ('\\"' + os.path.join(kit, "solynov_fx.exe")
                      + '\\" --dossier \\"' + kit + '\\.\\" --generer')
        else:
            action = ('py \\"' + os.path.join(kit, "solynov_worker.py")
                      + '\\" --dossier \\"' + kit + '\\.\\" --generer')
        freq = (_cfg.charger(self._config).get("gen_frequence") if _cfg else None) or 15
        return (f'schtasks /create /tn "{self._TACHE_GEN_AUTO}" /tr "{action}" '
                f'/sc minute /mo {int(freq)} /f')

    def installer_generation_auto(self):
        """Installe la génération automatique LOCALEMENT sur cet ordinateur (la tâche
        planifiée y tourne) et la programme — une seule autorisation Windows, sans
        quitter Solynov. Les tables et les Factur-X, eux, restent dans les dossiers
        partagés configurés au cadre 1."""
        if not sys.platform.startswith("win"):
            messagebox.showinfo("Génération automatique",
                "La génération automatique n'est disponible que sous Windows.")
            return
        cfg = _cfg.charger(self._config) if _cfg else {}
        if not cfg.get("table_principale"):
            messagebox.showinfo("Génération automatique", "Configurez d'abord vos "
                "données (bouton « Choisir le dossier »).")
            return
        try:
            kit, manquants = self._creer_kit(self._config)
        except Exception as e:
            messagebox.showerror("Génération automatique", f"Échec : {e}")
            return
        if any("licence" in m for m in manquants):
            messagebox.showwarning("Génération automatique",
                "Aucune licence active sur ce poste : la génération automatique ne "
                "démarrera pas. Activez votre licence (ou démarrez un essai), puis "
                "réinstallez.")
        elif (os.path.exists(os.path.join(self._config, "essai.jeton"))
              and not os.path.exists(os.path.join(self._config, "licence.lic"))):
            messagebox.showinfo("Génération automatique",
                "Pendant votre période d'essai, la génération automatique fonctionne "
                "aussi — mais, comme le reste, elle s'arrêtera à la fin de l'essai. "
                "Pensez à activer votre licence avant la fin pour ne pas l'interrompre.")
        if not self._run_bat_admin([self._cmd_planif_gen(kit)]):
            messagebox.showinfo("Génération automatique",
                "Installation annulée : autorisation Windows non accordée.")
            self._maj_voyants()
            return
        if _cfg:
            _cfg.maj(self._config, gen_auto_dossier=kit)
        self.root.after(1600, lambda: self._confirmer_install_gen())

    def _confirmer_install_gen(self):
        self._maj_voyants()
        if self._tache_existe(self._TACHE_GEN_AUTO):
            freq = (_cfg.charger(self._config).get("gen_frequence") if _cfg else None) or 15
            messagebox.showinfo("Génération automatique",
                "Génération automatique installée et active sur cet ordinateur.\n\n"
                f"Vos Factur-X seront produites toutes les {int(freq)} minutes.")
        else:
            messagebox.showwarning("Génération automatique",
                "L'installation n'a pas pu être confirmée (autorisation refusée ?). "
                "Réessayez si besoin.")

    def _changer_frequence_gen(self, valeur):
        """Change la fréquence de génération. Si la tâche est déjà installée, met à
        jour son intervalle (une autorisation Windows)."""
        try:
            freq = int(str(valeur).split()[0])
        except Exception:
            freq = 15
        if _cfg:
            _cfg.maj(self._config, gen_frequence=freq)
        # L'assistance (veilleur résident) vérifie en boucle toute seule : rien à
        # synchroniser de ce côté. On ne touche qu'à la tâche de génération.
        if self._tache_existe(self._TACHE_GEN_AUTO):
            if self._run_bat_admin([f'schtasks /change /tn "{self._TACHE_GEN_AUTO}" /ri {freq}']):
                self.root.after(1200, self._maj_voyants)

    def changer_generation_auto(self):
        """Boîte de dialogue au thème Solynov : désinstaller ou déplacer."""
        dossier = (_cfg.charger(self._config).get("gen_auto_dossier") if _cfg else None)
        win = ctk.CTkToplevel(self.root)
        win.title("Génération automatique")
        win.configure(fg_color=BLANC)
        win.resizable(False, False)
        win.transient(self.root)
        ctk.CTkLabel(win, text="Changer l'installation", text_color=NAVY,
                     font=self.f_marque).pack(anchor="w", padx=22, pady=(20, 4))
        ctk.CTkLabel(win, text=("Installée dans :\n" + dossier) if dossier
                     else "Génération automatique non installée.",
                     text_color=ARDOISE_L, font=self.f_small, justify="left",
                     wraplength=400).pack(anchor="w", padx=22, pady=(0, 16))
        ctk.CTkButton(win, text="Modifier le répertoire d'installation",
                      command=lambda: (win.destroy(), self._modifier_repertoire_gen()),
                      fg_color=BLEU, hover_color=BLEU_D, text_color=BLANC,
                      font=self.f_btn, height=36, corner_radius=8).pack(
            fill="x", padx=22, pady=(0, 8))
        rang = ctk.CTkFrame(win, fg_color=BLANC)
        rang.pack(fill="x", padx=22, pady=(0, 20))
        ctk.CTkButton(rang, text="Désinstaller",
                      command=lambda: (win.destroy(), self._desinstaller_generation_auto()),
                      fg_color=BLEU_LT, hover_color=BLEU_LT_D, text_color=NAVY,
                      border_color=BLEU_BORD, border_width=1, font=self.f_btn,
                      height=36, corner_radius=8).pack(side="left", expand=True,
                                                       fill="x", padx=(0, 4))
        ctk.CTkButton(rang, text="Annuler", command=win.destroy,
                      fg_color=BLANC, hover_color=SURVOL_L, text_color=ARDOISE,
                      border_color=BORD, border_width=1, font=self.f_btn,
                      height=36, corner_radius=8).pack(side="left", expand=True,
                                                       fill="x", padx=(4, 0))
        win.update_idletasks()
        try:
            win.grab_set()
        except Exception:
            pass

    def _modifier_repertoire_gen(self):
        """Déplace la génération auto : nouveau dossier, ancienne tâche supprimée et
        nouvelle installée en une seule autorisation ; l'ancien dossier est retiré."""
        ancien = (_cfg.charger(self._config).get("gen_auto_dossier") if _cfg else None)
        dest = filedialog.askdirectory(
            title="Nouveau dossier de la génération automatique",
            initialdir=self._dossier_initial())
        if not dest:
            return
        try:
            kit, _manq = self._creer_kit(dest)
        except Exception as e:
            messagebox.showerror("Génération automatique", f"Échec : {e}")
            return
        lignes = [f'schtasks /delete /tn "{self._TACHE_GEN_AUTO}" /f',
                  self._cmd_planif_gen(kit)]
        if not self._run_bat_admin(lignes):
            messagebox.showinfo("Génération automatique",
                "Déplacement annulé : autorisation Windows non accordée.")
            return
        if ancien and os.path.normcase(os.path.abspath(ancien)) != \
                os.path.normcase(os.path.abspath(kit)):
            shutil.rmtree(ancien, ignore_errors=True)
        if _cfg:
            _cfg.maj(self._config, gen_auto_dossier=kit)
        self.root.after(1600, lambda: self._confirmer_install_gen())

    def _desinstaller_generation_auto(self):
        """Supprime la tâche planifiée puis le dossier d'installation."""
        ancien = (_cfg.charger(self._config).get("gen_auto_dossier") if _cfg else None)
        if not self._run_bat_admin(
                [f'schtasks /delete /tn "{self._TACHE_GEN_AUTO}" /f']):
            messagebox.showinfo("Génération automatique",
                "Désinstallation annulée : autorisation Windows non accordée.")
            return
        if ancien:
            shutil.rmtree(ancien, ignore_errors=True)
        if _cfg:
            _cfg.maj(self._config, gen_auto_dossier=None)
        self.root.after(1400, lambda: (
            self._maj_voyants(),
            messagebox.showinfo("Génération automatique",
                                "Génération automatique désinstallée.")))

    # --- Auto-élévation Windows (une seule invite d'autorisation) ---
    def _run_admin(self, program, params):
        if not sys.platform.startswith("win"):
            return False
        try:
            import ctypes
            r = ctypes.windll.shell32.ShellExecuteW(
                None, "runas", program, params, None, 0)
            return int(r) > 32
        except Exception:
            return False

    def _run_bat_admin(self, lignes):
        """Écrit un .bat temporaire (commandes `lignes`) et l'exécute avec élévation.
        Renvoie True si l'utilisateur a accepté l'invite Windows."""
        if not sys.platform.startswith("win"):
            return False
        import tempfile
        try:
            fd, chemin = tempfile.mkstemp(suffix=".bat", prefix="solynov_")
            with os.fdopen(fd, "w", encoding="mbcs", errors="replace") as f:
                f.write("@echo off\r\n" + "\r\n".join(lignes)
                        + '\r\n(goto) 2>nul & del "%~f0"\r\n')
        except Exception:
            return False
        return self._run_admin("cmd.exe", f'/c "{chemin}"')

    def _tache_existe(self, nom):
        if not sys.platform.startswith("win"):
            return False
        try:
            r = subprocess.run(["schtasks", "/query", "/tn", nom],
                               capture_output=True, text=True,
                               creationflags=0x08000000)
            return r.returncode == 0
        except Exception:
            return False

    def _maj_voyants(self):
        """Met à jour les voyants (vert = actif, rouge = inactif) et l'état des boutons."""
        VERT = "#16A34A"
        ROUGE = "#DC2626"
        if hasattr(self, "voyant_gen"):
            actif = self._tache_existe(self._TACHE_GEN_AUTO)
            if actif:
                cfg = _cfg.charger(self._config) if _cfg else {}
                freq = cfg.get("gen_frequence") or 15
                dossier = cfg.get("gen_auto_dossier")
                self.voyant_gen.configure(text_color=VERT)
                self.lbl_gen.configure(
                    text=f"Génération automatique active — toutes les {int(freq)} min"
                    + (f"\nInstallée dans : {dossier}" if dossier else ""))
                self.btn_install_gen.configure(state="disabled")
                self.btn_changer_gen.configure(state="normal")
            else:
                self.voyant_gen.configure(text_color=ROUGE)
                self.lbl_gen.configure(text="Génération automatique non installée")
                self.btn_install_gen.configure(state="normal")
                self.btn_changer_gen.configure(state="disabled")
        if hasattr(self, "voyant_assist"):
            on = self._assistance_active()
            self.voyant_assist.configure(text_color=(VERT if on else ROUGE))
            self.lbl_assist.configure(text="Assistance active sur ce poste" if on
                else "Assistance non activée sur ce poste")

    # Anciennes tâches planifiées (migrées vers un veilleur résident depuis la v2.13).
    _TACHES_ASSISTANCE = ("Solynov - Assistance (session)",
                          "Solynov - Assistance (15 min)")
    _CLE_RUN = r"Software\Microsoft\Windows\CurrentVersion\Run"
    _VAL_RUN = "SolynovAssistance"

    def _cmd_assistance(self):
        """Ligne de commande du veilleur résident (stockée dans la clé Run)."""
        if getattr(sys, "frozen", False):
            return f'"{sys.executable}" --surveiller-resident'
        script = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                              "solynov_fx.py")
        return f'py "{script}" --surveiller-resident'

    def _assistance_active(self):
        """Vraie si le veilleur résident est enregistré au démarrage (clé Run)."""
        if not sys.platform.startswith("win"):
            return False
        try:
            import winreg
            with winreg.OpenKey(winreg.HKEY_CURRENT_USER, self._CLE_RUN) as k:
                winreg.QueryValueEx(k, self._VAL_RUN)
            return True
        except Exception:
            return False

    def _env_sans_pyi(self):
        """Environnement débarrassé des variables d'extraction PyInstaller, pour
        qu'un exe onefile relancé fasse sa propre extraction (sinon il chercherait
        ses ressources dans le _MEI du parent, supprimé à la fermeture)."""
        env = dict(os.environ)
        for kk in ("_MEIPASS2", "_PYI_ARCHIVE_INDEX", "_PYI_APPLICATION_HOME_DIR",
                   "_PYI_ONEDIR_MODE", "_PYI_PARENT_PROCESS_LEVEL", "_PYI_SPLASH_IPC"):
            env.pop(kk, None)
        return env

    def _lancer_veilleur_resident(self):
        """Démarre le veilleur MAINTENANT (sans attendre la prochaine ouverture de
        session), détaché, dans cette session interactive."""
        try:
            flags = 0x08000000 if sys.platform.startswith("win") else 0  # CREATE_NO_WINDOW
            if getattr(sys, "frozen", False):
                args = [sys.executable, "--surveiller-resident"]
            else:
                script = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                      "solynov_fx.py")
                args = [sys.executable, script, "--surveiller-resident"]
            subprocess.Popen(args, creationflags=flags, env=self._env_sans_pyi())
            return True
        except Exception:
            return False

    def _purger_ancienne_assistance(self):
        """Retire les anciennes tâches planifiées d'assistance si elles subsistent
        (elles « voleraient » l'anomalie sans pouvoir afficher la fenêtre). Tentative
        sans élévation, puis avec élévation seulement si nécessaire."""
        restantes = [n for n in self._TACHES_ASSISTANCE if self._tache_existe(n)]
        if not restantes:
            return
        for n in restantes:
            try:
                subprocess.run(["schtasks", "/delete", "/tn", n, "/f"],
                               capture_output=True, creationflags=0x08000000)
            except Exception:
                pass
        restantes = [n for n in self._TACHES_ASSISTANCE if self._tache_existe(n)]
        if restantes:   # créées en administrateur -> une élévation pour les retirer
            self._run_bat_admin([f'schtasks /delete /tn "{n}" /f' for n in restantes])

    def activer_assistance_poste(self):
        """Active sur CE poste le veilleur qui ouvre l'assistant quand la génération
        automatique a signalé des données à corriger. Depuis la v2.13 c'est un
        veilleur RÉSIDENT lancé au démarrage de session (clé Run) : il tourne dans la
        session interactive, donc la fenêtre d'aide s'affiche toujours (une tâche
        planifiée, elle, l'ouvrait sur un bureau invisible). Aucun droit admin requis."""
        if not sys.platform.startswith("win"):
            messagebox.showinfo(
                "Assistance sur ce poste",
                "L'assistance automatique n'est disponible que sous Windows.")
            return
        principale, _l = (_cfg.tables_valides(self._config) if _cfg else (None, []))
        if not principale:
            self._rediriger_cadre1()
            return
        try:
            import winreg
            with winreg.CreateKey(winreg.HKEY_CURRENT_USER, self._CLE_RUN) as k:
                winreg.SetValueEx(k, self._VAL_RUN, 0, winreg.REG_SZ, self._cmd_assistance())
        except Exception as e:
            messagebox.showerror("Assistance sur ce poste",
                f"Activation impossible : {e}")
            return
        # migration : retirer les anciennes tâches + repartir d'un marqueur propre,
        # puis démarrer le veilleur tout de suite.
        self._purger_ancienne_assistance()
        for f in ("arret_assistance", "derniere_empreinte_vue.txt"):
            try:
                os.remove(os.path.join(_config_dir_bureau(), f))
            except Exception:
                pass
        self._lancer_veilleur_resident()
        self.log("Assistance poste : activée.")
        self.root.after(600, lambda: (
            self._maj_voyants(),
            messagebox.showinfo("Assistance sur ce poste",
                "Assistance activée. Si une donnée manque, Solynov s'ouvrira sur "
                "ce poste pour vous aider à la corriger — dès maintenant et à chaque "
                "démarrage de session.")))

    def desactiver_assistance_poste(self):
        """Retire le veilleur du démarrage (clé Run) et arrête celui en cours."""
        if not sys.platform.startswith("win"):
            return
        try:
            import winreg
            with winreg.OpenKey(winreg.HKEY_CURRENT_USER, self._CLE_RUN, 0,
                                winreg.KEY_SET_VALUE) as k:
                winreg.DeleteValue(k, self._VAL_RUN)
        except Exception:
            pass
        # arrêt immédiat du veilleur en cours (il se termine au prochain cycle sinon)
        try:
            with open(os.path.join(_config_dir_bureau(), "arret_assistance"),
                      "w", encoding="utf-8") as f:
                f.write("stop")
        except Exception:
            pass
        self._purger_ancienne_assistance()
        self.log("Assistance poste : désactivée.")
        self.root.after(600, lambda: (
            self._maj_voyants(),
            messagebox.showinfo("Assistance sur ce poste",
                                "Assistance désactivée sur ce poste.")))

    def _ecrire_scripts_kit(self, kit):
        lanceur = (
            "@echo off\r\n"
            "cd /d \"%~dp0\"\r\n"
            "if exist \"%~dp0solynov_fx.exe\" (\r\n"
            "    \"%~dp0solynov_fx.exe\" --dossier \"%~dp0.\" --generer\r\n"
            ") else if exist \"%~dp0solynov_worker.exe\" (\r\n"
            "    \"%~dp0solynov_worker.exe\" --dossier \"%~dp0.\" --generer\r\n"
            ") else (\r\n"
            "    py \"%~dp0solynov_worker.py\" --dossier \"%~dp0.\" --generer\r\n"
            ")\r\n")
        installer = (
            "@echo off\r\n"
            "setlocal\r\n"
            "chcp 65001 >nul\r\n"
            "title Solynov - Installer la recuperation automatique\r\n"
            "set \"TACHE=Solynov - Recuperation auto\"\r\n"
            "set \"FREQUENCE=30\"\r\n"
            "echo.\r\n"
            "echo   SOLYNOV - Recuperation automatique des factures\r\n"
            "echo   ===============================================\r\n"
            "echo.\r\n"
            "echo   Genere vos Factur-X toutes les %FREQUENCE% minutes,\r\n"
            "echo   a partir des tables de ce dossier.\r\n"
            "echo.\r\n"
            "schtasks /create /tn \"%TACHE%\" /tr \"\\\"%~dp0solynov_fx.exe\\\" --dossier \\\"%~dp0.\\\" --generer\" /sc minute /mo %FREQUENCE% /f /rl highest >nul 2>nul\r\n"
            "if errorlevel 1 (\r\n"
            "    echo   [ECHEC] Installation impossible.\r\n"
            "    echo           Clic droit sur ce fichier ^> \"Executer en tant qu'administrateur\".\r\n"
            "    echo.\r\n"
            "    pause\r\n"
            "    exit /b 1\r\n"
            ")\r\n"
            "echo   [OK] Recuperation automatique installee.\r\n"
            "echo.\r\n"
            "echo   Journal : journal_recuperation.log\r\n"
            "echo   Pour arreter : desinstaller_recuperation_auto.bat\r\n"
            "echo.\r\n"
            "pause\r\n")
        desinstall = (
            "@echo off\r\n"
            "setlocal\r\n"
            "chcp 65001 >nul\r\n"
            "title Solynov - Desinstaller la recuperation automatique\r\n"
            "set \"TACHE=Solynov - Recuperation auto\"\r\n"
            "echo.\r\n"
            "schtasks /delete /tn \"%TACHE%\" /f >nul 2>nul\r\n"
            "if errorlevel 1 (\r\n"
            "    echo   [INFO] Aucune tache Solynov a supprimer ^(ou droits insuffisants^).\r\n"
            ") else (\r\n"
            "    echo   [OK] Recuperation automatique arretee et supprimee.\r\n"
            ")\r\n"
            "echo.\r\n"
            "pause\r\n")
        lisezmoi = (
            "SOLYNOV - RECUPERATION AUTOMATIQUE (serveur)\n"
            "============================================\n\n"
            "Ce dossier genere vos Factur-X automatiquement sur la machine de\n"
            "gestion, a partir de vos tables exportees. Solynov ne modifie jamais\n"
            "vos donnees : il les lit, c'est tout.\n\n"
            "INSTALLATION (3 etapes)\n"
            "-----------------------\n"
            "1) Copiez ce dossier sur le serveur.\n"
            "2) Verifiez config_tables.json (Bloc-notes) : les chemins doivent etre\n"
            "   ceux vus DEPUIS LE SERVEUR, antislashs doubles (C:\\\\dossier\\\\...).\n"
            "3) Clic droit sur installer_recuperation_auto.bat > Executer en tant\n"
            "   qu'administrateur.\n\n"
            "VERIFIER\n"
            "--------\n"
            "- journal_recuperation.log : compte-rendu de chaque passage.\n"
            "- Generation immediate : double-clic sur lancer_generation.bat.\n\n"
            "ARRETER : desinstaller_recuperation_auto.bat.\n\n"
            "ERREURS : le journal indique la donnee manquante (ex. avoir sans\n"
            "facture d'origine). Corrigez dans votre logiciel de gestion et\n"
            "re-exportez. Jamais dans le registre Solynov.\n")
        for nom, contenu in (("lancer_generation.bat", lanceur),
                             ("installer_recuperation_auto.bat", installer),
                             ("desinstaller_recuperation_auto.bat", desinstall),
                             ("LISEZMOI_serveur.txt", lisezmoi)):
            with open(os.path.join(kit, nom), "w", encoding="utf-8",
                      newline="") as f:
                f.write(contenu)

    def _maj_lbl_mode(self):
        if not hasattr(self, "lbl_mode"):
            return
        mode = (_cfg.charger(self._config).get("mode_installation") if _cfg else None)
        txt = {"local": "sur cet ordinateur",
               "serveur": "sur un serveur séparé"}.get(mode, "non définie")
        self.lbl_mode.configure(text=f"Installation de la génération automatique : {txt}")

    def _appliquer_mode(self):
        mode = (_cfg.charger(self._config).get("mode_installation") if _cfg else None)
        montrer = BRIDGE_DISPO and mode == "serveur"
        try:
            if montrer:
                self.zone_kit.grid()
            else:
                self.zone_kit.grid_remove()
        except Exception:
            pass
        self._maj_lbl_mode()

    def _maybe_aiguillage(self):
        if not BRIDGE_DISPO:
            return
        vu = (_cfg.charger(self._config).get("accueil_vu") if _cfg else True)
        if not vu:
            self._afficher_aiguillage()

    def _choisir_mode(self, mode):
        if _cfg:
            _cfg.maj(self._config, mode_installation=mode, accueil_vu=True)
        self._appliquer_mode()
        try:
            self._overlay_aig.destroy()
        except Exception:
            pass

    def _changer_mode(self):
        self._afficher_aiguillage()

    def _afficher_aiguillage(self):
        ov = ctk.CTkFrame(self.root, fg_color=BLANC, corner_radius=0)
        ov.place(x=0, y=0, relwidth=1, relheight=1)
        self._overlay_aig = ov
        wrap = ctk.CTkFrame(ov, fg_color=BLANC)
        wrap.place(relx=0.5, rely=0.5, anchor="center")

        head = ctk.CTkFrame(wrap, fg_color=BLANC)
        head.pack(fill="x", pady=(0, 12))
        ctk.CTkLabel(head, text="S", width=34, height=34, corner_radius=9,
                     fg_color=BLEU, text_color=BLANC,
                     font=ctk.CTkFont(size=17, weight="bold")).pack(side="left")
        ctk.CTkLabel(head, text="Bienvenue dans Solynov", text_color=NAVY,
                     font=self.f_marque).pack(side="left", padx=(10, 0))

        enc = ctk.CTkFrame(wrap, fg_color=BLEU_LT, border_color=BLEU_BORD,
                           border_width=1, corner_radius=12)
        enc.pack(fill="x", pady=(0, 14))
        ctk.CTkLabel(enc, text="Comment Solynov lit vos données",
                     text_color=BLEU_D, font=self.f_h).pack(anchor="w", padx=14, pady=(11, 2))
        ctk.CTkLabel(
            enc, text="Solynov ne se connecte pas à votre logiciel de gestion. Vous lui\n"
            "fournissez des exports tableur (Excel, OpenOffice…) de vos tables —\n"
            "factures, clients, articles — qui se rafraîchissent à chaque nouvelle\n"
            "facture créée. C'est à vous de les mettre en place : vous seul\n"
            "connaissez votre système.",
            text_color=BLEU_D, font=self.f_small, justify="left").pack(
            anchor="w", padx=14, pady=(0, 11))

        ctk.CTkLabel(wrap,
                     text="Où tourne votre logiciel de gestion qui produit les factures ?",
                     text_color=NAVY, font=self.f_h).pack(anchor="w", pady=(0, 10))

        cartes = ctk.CTkFrame(wrap, fg_color=BLANC)
        cartes.pack(fill="x")

        def carte(cote, titre, desc, mode):
            c = ctk.CTkFrame(cartes, fg_color=FOND, border_color=BORD,
                             border_width=1, corner_radius=12, width=252, height=176)
            c.pack(side="left", padx=(0 if cote == 0 else 12, 0))
            c.pack_propagate(False)
            ctk.CTkLabel(c, text=titre, text_color=NAVY, font=self.f_h).pack(
                anchor="w", padx=14, pady=(16, 3))
            ctk.CTkLabel(c, text=desc, text_color=ARDOISE_L, font=self.f_small,
                         justify="left", wraplength=214).pack(anchor="w", padx=14)
            ctk.CTkButton(c, text="Choisir", command=lambda m=mode: self._choisir_mode(m),
                          height=32, corner_radius=8, fg_color=BLEU, hover_color=BLEU_D,
                          text_color=BLANC, font=self.f_btn).pack(
                side="bottom", fill="x", padx=14, pady=14)
        carte(0, "Sur cet ordinateur",
              "Tout est ici. Solynov lit vos exports et génère sur ce PC.", "local")
        carte(1, "Sur un serveur séparé",
              "Votre gestion tourne sur un serveur. Vous y installerez la "
              "récupération auto.", "serveur")

    def _pbtn(self, parent, txt, cmd):
        b = ctk.CTkButton(parent, text=txt, command=cmd, height=30, corner_radius=8,
                          fg_color=BLEU_LT, hover_color=BLEU_LT_D, text_color=NAVY,
                          border_color=BLEU_BORD, border_width=1, font=self.f_btn)
        b.pack(side="left", padx=4)
        return b

